function buildItems(script: Script, group: KanaGroup, seeds: readonly KanaSeed[]): KanaItem[] {
  return seeds.map(([hira, romaji, extra]) => {
    const glyph = script === 'hiragana' ? hira : toKatakana(hira)
    const mnemonic =
      group === 'basic'
        ? script === 'hiragana'
          ? HIRAGANA_MNEMONICS[hira]
          : KATAKANA_MNEMONICS[glyph]
        : undefined

    return {
      id: kanaId(script, glyph),
      type: 'kana',
      glyph,
      romaji,
      alts: [...(extra ?? [])],
      script,
      group,
      mnemonic,
    }
  })
}

export const KANA_ITEMS: KanaItem[] = [
  ...buildItems('hiragana', 'basic', BASIC),
  ...buildItems('hiragana', 'dakuten', DAKUTEN),
  ...buildItems('hiragana', 'yoon', YOON),
  ...buildItems('katakana', 'basic', BASIC),
  ...buildItems('katakana', 'dakuten', DAKUTEN),
  ...buildItems('katakana', 'yoon', YOON),
]
